using HTBAM.Application.Interfaces; using HTBAM.Infrastructure.Data; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace HTBAM.Api.Controllers;
[ApiController,Authorize,Route("api/system")]
public sealed class SystemController(AppDbContext db,IAiClient ai,IObjectStorage storage,IConfiguration cfg):ControllerBase
{
 [HttpGet("capabilities")]public async Task<ActionResult> Capabilities(CancellationToken ct){var aiHealth=await ai.HealthAsync(ct);var caps=aiHealth?await ai.CapabilitiesAsync(ct):new HTBAM.Application.DTOs.AiCapabilitiesResponse(false,false,false,Array.Empty<string>());var developmentDataWarning=await db.AcademicTerms.AnyAsync(x=>x.IsDevelopment,ct)?HTBAM.Api.Support.DemoDataSeeder.Warning:null;return Ok(new{developmentDataWarning,web=true,backend=true,database=await db.Database.CanConnectAsync(ct),objectStorage=await storage.HealthAsync(ct),aiHealth,sessionInference=caps.SessionInference,faceEnrollment=caps.FaceEnrollment,annotatedVideoOutput=caps.AnnotatedVideoOutput,loadedModels=caps.LoadedModels,llmProvider=cfg["Llm:Provider"]??"NOT_CONFIGURED",modelIntegrationPending=!caps.SessionInference||!caps.FaceEnrollment||!caps.AnnotatedVideoOutput});}
 [HttpGet("counts")]public async Task<ActionResult> Counts(CancellationToken ct){var tid=await HTBAM.Api.Support.AccessScope.TeacherIdAsync(db,User,ct);var sessions=HTBAM.Api.Support.AccessScope.Sessions(db,User,tid);var sessionIds=sessions.Select(x=>x.Id);var classIds=sessions.Select(x=>x.ClassSectionId);var studentIds=db.SessionStudentsSet.Where(x=>sessionIds.Contains(x.SessionId)).Select(x=>x.StudentId);var videos=HTBAM.Api.Support.AccessScope.Videos(db,User,tid);return Ok(new{students=await db.StudentsSet.CountAsync(x=>x.IsActive&&studentIds.Contains(x.Id),ct),classSections=await db.ClassSections.CountAsync(x=>x.IsActive&&classIds.Contains(x.Id),ct),sessions=await sessions.CountAsync(ct),openAlerts=await db.AlertsSet.CountAsync(x=>x.Status=="OPEN"&&sessionIds.Contains(x.SessionId),ct),cameras=await db.CamerasSet.CountAsync(x=>x.IsActive,ct),videos=await videos.CountAsync(x=>x.Status=="READY",ct)});}
}
